def finding(item, ordinal, refs):
    fid, name, primary = item
    low = name.lower()
    kinds = [primary, KINDS[(ordinal + 7) % len(KINDS)], KINDS[(ordinal + 16) % len(KINDS)]]
    return {
        "id": fid, "name": name,
        "description": f"Records {low} as source-qualified Payroll / Compensation context while worker, engagement, job, timekeeping, leave, expense, benefit, tax, payment, ledger, filing, dispute and records masters remain independently identifiable.",
        "source_refs": refs,
        "questions": [
            {"id": f"{fid}-q01", "text": f"Which stable payroll run, payee result, worker, engagement, period, jurisdiction, revision and external-master identities establish {low}?", "kind": kinds[0], "answer_data": ["payroll-run, payee-result, worker, engagement, employer, pay-group, period, jurisdiction, revision and master-system identifiers", "regular, supplemental, off-cycle, final, advance, retroactive, correction, reversal and void profiles", "proposed, input-closed, calculated, validated, approved, released, paid, filed, closed, disputed, corrected and superseded states"]},
            {"id": f"{fid}-q02", "text": f"Who supplies, calculates, approves, receives, reports, remits, audits, challenges or may rely on {low}, for which purpose and under what authority?", "kind": kinds[1], "answer_data": ["worker, employer, payroll administrator, compensation authority, manager, time approver, benefit provider, tax authority, garnishment authority, payment provider and auditor", "employment term, collective agreement, statute, court order, worker election, delegated role, policy, jurisdiction and segregation of duties", "eligibility, priority, threshold, ceiling, floor, proration, exception, privacy, accountability and contestability"]},
            {"id": f"{fid}-q03", "text": f"Which amount type, currency, unit, rule version, source, evidence, method, period, event time, observation time, uncertainty, correction lineage and projection loss qualify {low}?", "kind": kinds[2], "answer_data": ["earning, basis, deduction, contribution, tax, net-pay, employer-cost and reconciliation amount types plus currency, unit and rounding", "rate, quantity, table, formula, threshold, accumulator, input evidence, intermediate result, validation and authority response", "earning, effective, cutoff, calculation, approval, payment, settlement, filing, observation, ingestion and knowledge times, predecessor, successor, retention, access and mapping loss"]},
        ],
        "data_elements": [{"id": f"{fid}-data", "name": f"{name} data", "description": f"Typed payroll or compensation data for {low}, qualified by source, authority, rule, version, period, time, currency, uncertainty, privacy and provenance.", "value_kind": "object", "cardinality": "1", "required": True, "source_refs": refs}],
        "artifacts": [{"id": f"{fid}-record", "name": f"{name} record", "description": f"Immutable or versioned evidence for {low} with payroll-run and payee-result identity, digest, source, rule version, event and knowledge times, access marking and revision lineage.", "media_or_form": ["application/yaml", "application/json", "text/markdown", "text/html"], "serial": True, "identity_strategy": "Prefer the authoritative payroll, employer, authority, payment or filing identifier; otherwise use a governed IRI, then a Dimension UUID or ULID.", "source_refs": refs}],
        "inline_only_rationale": None,
    }


def structure():
    bundles = []
    ordinal = 0
    for bid, bname, rationale, layers in ROWS:
        built_layers = []
        bundle_refs = []
        for lid, lname, refs, items in layers:
            fs = []
            for item in items:
                ordinal += 1
                fs.append(finding(item, ordinal, refs))
            built_layers.append({"id": lid, "name": lname, "description": f"Groups governed {lname.lower()} for Payroll / Compensation.", "source_refs": refs, "findings": fs})
            bundle_refs.extend(refs)
        bundles.append({"id": bid, "name": bname, "description": rationale, "rationale": rationale, "source_refs": list(dict.fromkeys(bundle_refs)), "layers": built_layers})
    return {"bundles": bundles}


